-- Initialization
sort(TableBrowser_Temp)
local MAX_TABLES = 8
SEARCH_COUNT = 38

_G["ItemLinkerTableListTip"]:SetText("Shift-Click to link item in chat\n Left-Click to show item tooltip.")

do
	local entry = CreateFrame("Button", "$parentEntry1", ItemLinkerTableList, "ItemLinkerEntry1")
	entry:SetID(1)
	entry:SetPoint("TOPLEFT", 4, -4)
	for i = 2, MAX_TABLES do
		local entry = CreateFrame("Button", "$parentEntry"..i, ItemLinkerTableList, "ItemLinkerEntry"..(2 - (i % 2)))
		entry:SetID(i)
		entry:SetPoint("TOP", "$parentEntry"..(i -1 ), "BOTTOM")
	end
end

-- Search Function
_G["ItemLinkerSearchBox"]:HookScript("OnTextChanged", function(self, userInput)
	local searchtxt = _G["ItemLinkerSearchBox"]:GetText()
	SEARCH_COUNT = 0

	for i = 1,#TableBrowser do
		TableBrowser[i] = nil
	end

	for i = 1,#TableBrowser_Temp do
		if string.find((TableBrowser_Temp[i]),(searchtxt)) ~= nil then
			SEARCH_COUNT = SEARCH_COUNT + 1
		end
	end

	if SEARCH_COUNT == 0 then
		_G["ItemLinkerTableListInfo"]:SetText("No search results.\n ItemLinker is case-sensitive.")
	elseif SEARCH_COUNT < 38 then
		_G["ItemLinkerTableListInfo"]:SetText("")
		for i = 1,#TableBrowser_Temp do
			if string.find((TableBrowser_Temp[i]),(searchtxt)) ~= nil then
				table.insert(TableBrowser,TableBrowser_Temp[i])
			end
		end
	else
		_G["ItemLinkerTableListInfo"]:SetText(""..SEARCH_COUNT.." items in search.\n Please refine your search...")
	end

	TableBrowser.Update()
end)

function ItemLinker_Search(text)
	local searchtxt = text
	_G["ItemLinkerSearchBox"]:SetText(searchtxt)
	SEARCH_COUNT = 0

	for i = 1,#TableBrowser do
		TableBrowser[i] = nil
	end

	for i = 1,#TableBrowser_Temp do
		if string.find((TableBrowser_Temp[i]),(searchtxt)) ~= nil then
			SEARCH_COUNT = SEARCH_COUNT + 1
		end
	end

	if SEARCH_COUNT == 0 then
		_G["ItemLinkerTableListInfo"]:SetText("No search results.\n ItemLinker is case-sensitive.")
	elseif SEARCH_COUNT < 38 then
		_G["ItemLinkerTableListInfo"]:SetText("")
		for i = 1,#TableBrowser_Temp do
			if string.find((TableBrowser_Temp[i]),(searchtxt)) ~= nil then
				table.insert(TableBrowser,TableBrowser_Temp[i])
			end
		end
	else
		_G["ItemLinkerTableListInfo"]:SetText(""..SEARCH_COUNT.." items in search.\n Please refine your search...")
	end

	TableBrowser.Update()
end
search = ItemLinker_Search

-- Shows searched items
function TableBrowser.Update()
	for i = 1, MAX_TABLES do
		local entry = TableBrowser[i + ItemLinkerTableListScrollFrame.offset]
		local frame = getglobal("ItemLinkerTableListEntry"..i)
		if entry then
			frame:Show()
			local temp = getglobal(frame:GetName())
			temp:SetText(entry)
			local r, g, b, hex = GetItemQualityColor(TableBrowser.Tables[entry][2])
			temp:GetFontString():SetTextColor(r,g,b)
			local itemnum = TableBrowser.Tables[entry][1]
			local rarity  = TableBrowser.Tables[entry][2]
			frame:SetScript("OnClick", function(self,button,down)
			local itemName, itemLink, itemRarity, itemLevel, itemMinLevel, itemType, itemSubType, itemStackCount,itemEquipLoc, itemTexture, itemSellPrice = GetItemInfo(itemnum)
				if itemLink ~= nil then
					if  IsModifiedClick() then
						ChatFrame1EditBox:Insert(itemLink)
					else
						ShowUIPanel(GameTooltip)
						GameTooltip:SetOwner(frame, "ANCHOR_RIGHT")
						GameTooltip:SetHyperlink(itemLink)
						GameTooltip:Show()
					end
				end
			end)


			frame:SetScript("OnLeave", function(self)
				GameTooltip:Hide()
			end)


		else
			frame:Hide()
		end
	end
	FauxScrollFrame_Update(ItemLinkerTableListScrollFrame, #TableBrowser, MAX_TABLES, 21,nil,nil,nil,nil,nil,nil,true)
end


TableBrowser.Update()

